typedef unsigned int nlUint32;
typedef int nlInt32;
typedef nlUint32 nslSourceId;
typedef nlUint32 nslSoundId;
typedef nlUint32 nslEmitterId;

enum nslSoundParamEnum
{
  NSL_SOUNDPARAM_VOLUME,
  NSL_SOUNDPARAM_PITCH,
  NSL_SOUNDPARAM_MINDIST,
  NSL_SOUNDPARAM_MAXDIST,
  NSL_SOUNDPARAM_Z
};

extern "C" void nslFatal(const char *, ...);

struct nslSound
{
  bool isReady;
  bool used;
  bool inRange;
  bool isReallyReady;
  bool isPlaying;
  bool isReallyPlaying;
  bool looping;
  bool isQueuing;
  short left;
  short right;
  short old_left;
  short old_right;
  nlUint32 gasInstanceId;
  nlInt32 pauseCount;
  nlInt32 dampenCount;
  nslSourceId myId;
  nslSourceId mySource;
  nslEmitterId myEmitter;
  float rawVolume;
  float positionalVolume;
  float angle;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSystem
{
  char beforeSoundSlots[0xC044];
  nslSound soundSlots[256];
  char beforeInitialized[0x2C];
  nlInt32 initialized;
  char beforeOn[0x2C];
  bool on;
};

extern nslSystem nsl;

inline void _nslCheckSoundIdValidity(nslSoundId checkId)
{
  nslSoundId checkSlot = (checkId & 0x000003FF);
  nslSoundId upCheckId = (checkId & 0xFFFFFC00);
  if (checkId == 0)
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(nsl.soundSlots[checkSlot].used))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(checkSlot < 256))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(checkId == nsl.soundSlots[checkSlot].myId))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(upCheckId > 0))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (checkSlot > 256)
    nslFatal("Bad Sound ID 0x%x SLOT NUMBER ABOVE SLOTS\n", checkId);
}

inline void _nslInitialized()
{
  if (!(nsl.initialized == 1))
    nslFatal("NSL NOT INITIALIZED");
}

float nslGetSoundParam( nslSoundId whichSound, nslSoundParamEnum whichParam )
{

  if (!nsl.on) return 1.0f;
  _nslInitialized();
  _nslCheckSoundIdValidity(whichSound);
  switch (whichParam) {
    case NSL_SOUNDPARAM_VOLUME: 
      return nsl.soundSlots[(whichSound&0x000003FF)].rawVolume; break;
    case NSL_SOUNDPARAM_PITCH:
      return nsl.soundSlots[(whichSound&0x000003FF)].pitch; break;
    case NSL_SOUNDPARAM_MINDIST:
      return nsl.soundSlots[(whichSound&0x000003FF)].minDist; break;
    case NSL_SOUNDPARAM_MAXDIST:
      return nsl.soundSlots[(whichSound&0x000003FF)].maxDist; break;
    default: nslFatal(false && "Unhandled sourcetype"); break;
  }
  return 0.0f;
}
